#include <bits/stdc++.h>
using namespace std;
const int MAXNODES = 577;
int n, m, Mod, dp[MAXNODES], dp2[MAXNODES], C[MAXNODES][MAXNODES], res[MAXNODES][MAXNODES], res2[MAXNODES][MAXNODES];

inline int sumInterval(int start, int end) {
    return ((start + end) * 1LL * (end - start + 1) / 2) % Mod;
}

int main() {
    scanf("%d%d%d", &n, &m, &Mod);
    for (int i = 0; i < MAXNODES; ++i) {
        C[i][0] = 1;
        C[i][i] = 1;
    }
    for (int i = 1; i < MAXNODES; ++i) {
        for (int j = 1; j < i; ++j) {
            C[j][i] = (C[j][i - 1] + C[j - 1][i - 1]) % Mod;
        }
    }
    dp[0] = 1; dp2[0] = 0;
    for (int length = 1; length <= n; ++length) {
        for (int i = 1; i <= length; ++i) {
            int sum_val = sumInterval(1, i - 1) + sumInterval(1, length - i);
            int total = length + 1;
            long long val1 = (long long)dp[i - 1] * total % Mod * dp[length - i] % Mod * C[i - 1][length - 1];
            long long val2 = (long long)sum_val * dp[i - 1] % Mod * dp[length - i] % Mod * C[i - 1][length - 1];
            long long val3 = (long long)dp2[i - 1] * total % Mod * dp[length - i] % Mod * C[i - 1][length - 1];
            long long val4 = (long long)dp2[length - i] * total % Mod * dp[i - 1] % Mod * C[i - 1][length - 1];

            dp[length] = (dp[length] + val1) % Mod;
            dp2[length] = (dp2[length] + val2 + val3 + val4) % Mod;
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= m && j <= i; ++j) {
            res[i][j] = res[i - 1][j];
            res2[i][j] = res2[i - 1][j];
            for (int h = 1; h < j; ++h) {
                res[i][j] = (res[i][j] + (long long)res[i - h - 1][j - h] * dp[h] % Mod * C[h][j]) % Mod;
                res2[i][j] = (res2[i][j] + (long long)res2[i - h - 1][j - h] * dp[h] % Mod * C[h][j]) % Mod;
                res2[i][j] = (res2[i][j] + (long long)res[i - h - 1][j - h] * dp2[h] % Mod * C[h][j]) % Mod;
            }
            res[i][j] = (res[i][j] + dp[j]) % Mod;
            res2[i][j] = (res2[i][j] + dp2[j]) % Mod;
        }
    }
    printf("%d\n", res2[n][m]);
    return 0;
}
